import os, json, glob, time, math
from typing import Dict, List, Any, Optional

# ---------- IO helpers ----------
def _read_jsonl(path: str) -> List[Dict[str, Any]]:
    if not os.path.exists(path):
        return []
    out: List[Dict[str, Any]] = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                out.append(json.loads(line))
            except Exception:
                pass
    return out

def load_beacons(dir_path: str = 'storage/shared/meta/sas/beacons') -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    os.makedirs(dir_path, exist_ok=True)
    for p in glob.glob(os.path.join(dir_path, '*.jsonl')):
        records.extend(_read_jsonl(p))
    return records

def latest_by_agent(dir_path: str = 'storage/shared/meta/sas/beacons') -> Dict[str, Dict[str, Any]]:
    latest: Dict[str, Dict[str, Any]] = {}
    for rec in load_beacons(dir_path):
        a = rec.get('agent') or 'unknown'
        prev = latest.get(a)
        if prev is None or (rec.get('ts', 0) >= prev.get('ts', 0)):
            latest[a] = rec
    return latest

# ---------- Trend utilities (v0.1) ----------
def _median(xs: List[float]) -> float:
    if not xs:
        return 0.0
    ys = sorted(xs)
    n = len(ys)
    m = n // 2
    if n % 2:
        return ys[m]
    return 0.5 * (ys[m-1] + ys[m])

def _mad(xs: List[float], med: float) -> float:
    if not xs:
        return 0.0
    devs = [abs(x - med) for x in xs]
    return _median(devs)

def _recent_sentinel_deltas(recs: List[Dict[str, Any]], window: int = 5) -> List[float]:
    vals: List[float] = []
    for rec in sorted(recs, key=lambda r: r.get('ts', 0), reverse=True):
        sd = rec.get('sentinel_delta')
        if sd is not None:
            try:
                vals.append(float(sd))
            except Exception:
                pass
        if len(vals) >= window:
            break
    return list(reversed(vals))

def compute_trends(dir_path: str = 'storage/shared/meta/sas/beacons', window: int = 5) -> Dict[str, Dict[str, float]]:
    """
    Returns per-agent trends dict:
      {agent: {"delta_ma5": ..., "delta_mad5": ..., "volatility_index": ...}}
    Aggregator computes if absent in beacons.
    """
    by_agent: Dict[str, List[Dict[str, Any]]] = {}
    for rec in load_beacons(dir_path):
        a = rec.get('agent') or 'unknown'
        by_agent.setdefault(a, []).append(rec)

    trends: Dict[str, Dict[str, float]] = {}
    for agent, recs in by_agent.items():
        recent = _recent_sentinel_deltas(recs, window=window)
        if not recent:
            continue
        mean = sum(recent) / len(recent)
        med = _median(recent)
        mad = _mad(recent, med)
        voli = (mad / (abs(mean) + 1e-9)) if mean != 0 else 0.0
        trends[agent] = {"delta_ma5": mean, "delta_mad5": mad, "volatility_index": voli}
    return trends

# ---------- Robust parsing helpers ----------
def _to_state(value: Any, default: str = 'Active') -> str:
    """Coerce 'state' to a canonical string, handling non-strings gracefully."""
    try:
        if isinstance(value, str):
            s = value
        elif isinstance(value, dict):
            # Try common keys; else stringify
            s = value.get('value') or value.get('name') or str(value)
        else:
            s = str(value)
    except Exception:
        s = default
    s = (s or default).strip()
    return s.capitalize() if s else default

def _to_float(value: Any, default: float) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)

# ---------- Policy ----------
def simple_policy(beacon: Optional[Dict[str, Any]], trends: Optional[Dict[str, float]] = None) -> Dict[str, Any]:
    """Return minimal pacing advice for a single agent."""
    if not isinstance(beacon, dict):
        return {"allowed": False, "pace": 0.0, "path_policy": "shallow_simple", "reason": "no_beacon"}

    state = _to_state(beacon.get('state', 'Active'), default='Active')
    # Prefer trend volatility; fallback to beacon-provided; else 0
    voli = 0.0
    if isinstance(trends, dict) and 'volatility_index' in trends:
        voli = _to_float(trends.get('volatility_index'), 0.0)
    elif 'volatility_index' in beacon:
        voli = _to_float(beacon.get('volatility_index'), 0.0)

    if state == 'Active':
        return {"allowed": False, "pace": 0.0, "path_policy": "shallow_simple", "reason": "active_cooldown"}

    if state == 'Borderline':
        pace = 0.25 if voli < 0.6 else 0.2
        return {"allowed": True, "pace": pace, "path_policy": "shallow_simple", "reason": "borderline_paced"}

    # Clean (default)
    base = _to_float(beacon.get('recommended_pace', 0.8), 0.8)
    pace = min(1.0, base) if voli < 0.6 else min(0.6, base)
    return {"allowed": True, "pace": pace, "path_policy": "shallow_simple", "reason": "clean_ok_with_volatility"}

def advise_all(dir_path: str = 'storage/shared/meta/sas/beacons', window: int = 5) -> Dict[str, Dict[str, Any]]:
    latest = latest_by_agent(dir_path)
    trends = compute_trends(dir_path, window=window)
    out: Dict[str, Dict[str, Any]] = {}
    for agent, b in latest.items():
        out[agent] = simple_policy(b, trends.get(agent))
    return out



